import sys

def is_palindrome(s):
    return s == s[::-1]

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    results = []
    index = 1
    for _ in range(T):
        A = input[index]
        B = input[index + 1]
        found = False
        for i in range(len(A)):
            for j in range(i + 1, len(A) + 1):
                for k in range(len(B)):
                    for l in range(k + 1, len(B) + 1):
                        if is_palindrome(A[i:j] + B[k:l]):
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
        results.append("Yes" if found else "No")
        index += 2
    print("\n".join(results))

if __name__ == "__main__":
    main()
